# ownedBoundary non-overlap check (ancestor/descendant)
def is_ancestor(a, b):
    # a is ancestor of b if b == a or b starts with a + '/'
    return b == a or b.startswith(a.rstrip('/') + '/')

all_paths = []
for t in tasks:
    for p in t['ownedBoundary']:
        all_paths.append((t['id'], p))

for i in range(len(all_paths)):
    for j in range(len(all_paths)):
        if i == j: continue
        id_i, p_i = all_paths[i]
        id_j, p_j = all_paths[j]
        if id_i == id_j: continue
        if is_ancestor(p_i, p_j):
            print(f"OVERLAP: {id_i}:{p_i} is ancestor of {id_j}:{p_j}")

# protected boundary check
protected_prefixes = ['.claude', 'docs/solution-design.md']
for t in tasks:
    for p in t['ownedBoundary']:
        for pp in protected_prefixes:
            assert not p.startswith(pp), f"{t['id']} touches protected {p}"
        assert not p.startswith('/') and '..' not in p, f"bad path {p} in {t['id']}"

# dependsOn DAG check - only reference ids in plan
id_set = set(ids)
for t in tasks:
    for dep in t['dependsOn']:
        assert dep in id_set, f"{t['id']} depends on unknown {dep}"
        assert dep != t['id'], f"{t['id']} self-reference"

# cycle check (simple DFS)
graph = {t['id']: t['dependsOn'] for t in tasks}
def has_cycle():
    visited = {}
    def dfs(n):
        visited[n] = 1
        for m in graph[n]:
            if visited.get(m) == 1:
                return True
            if visited.get(m) != 2 and dfs(m):
                return True
        visited[n] = 2
        return False
    for n in graph:
        if visited.get(n) is None:
            if dfs(n):
                return True
    return False
assert not has_cycle(), "cycle detected"

# milestone terminal check
milestones = [t['id'] for t in tasks if t['unitType'] == 'milestone']
assert len(milestones) == 1, milestones
ms = milestones[0]
for t in tasks:
    if t['id'] != ms:
        assert ms not in t['dependsOn'], f"{t['id']} depends on milestone {ms} - not terminal"

# all implementation tasks should be depended on by milestone (per spec: "모든(또는 종단) implementation 단위에 dependsOn")
impl_ids = [t['id'] for t in tasks if t['unitType'] == 'implementation']
ms_task = [t for t in tasks if t['id'] == ms][0]
missing_dep = [i for i in impl_ids if i not in ms_task['dependsOn']]
assert not missing_dep, f"milestone missing deps on: {missing_dep}"

# delegation 8 fields
deleg_keys = {'from','to','task','input','output','done','context','constraints'}
for t in tasks:
    dk = set(t['delegation'].keys())
    assert dk == deleg_keys, f"{t['id']} delegation keys mismatch: {dk}"
    assert t['role'] == 'Worker', t['id']
    assert t['model'] == 'sonnet', t['id']
    assert t['ownedBoundary'], f"{t['id']} empty ownedBoundary"

print("ALL STRUCTURAL CHECKS PASSED")
print(f"tasks: {ids}")
print(f"milestone: {ms}, deps: {ms_task['dependsOn']}")
